{
  "title": "agent.completions.message.SimpleContentExpression",
  "description": "Expression variant of [`SimpleContent`] for dynamic content.",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part text content expressions.",
      "type": "array",
      "items": {
        "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
        "anyOf": [
          {
            "description": "An expression (JMESPath or Starlark) to evaluate.",
            "$ref": "functions.expression.Expression"
          },
          {
            "description": "A literal value.",
            "$ref": "agent.completions.message.SimpleContentPartExpression"
          }
        ]
      }
    }
  ]
}

{
  "title": "functions.expression.InputSchema",
  "description": "Schema for validating Function input.\n\nDefines the expected structure and constraints for input data.\nUsed by remote Functions to document and validate their inputs.",
  "anyOf": [
    {
      "description": "A union of schemas - input must match at least one.",
      "$ref": "functions.expression.AnyOfInputSchema"
    },
    {
      "description": "An object with named properties.",
      "$ref": "functions.expression.ObjectInputSchema"
    },
    {
      "description": "An array of items.",
      "$ref": "functions.expression.ArrayInputSchema"
    },
    {
      "description": "A string value.",
      "$ref": "functions.expression.StringInputSchema"
    },
    {
      "description": "An integer value.",
      "$ref": "functions.expression.IntegerInputSchema"
    },
    {
      "description": "A floating-point number.",
      "$ref": "functions.expression.NumberInputSchema"
    },
    {
      "description": "A boolean value.",
      "$ref": "functions.expression.BooleanInputSchema"
    },
    {
      "description": "An image (URL or base64).",
      "$ref": "functions.expression.ImageInputSchema"
    },
    {
      "description": "Audio content.",
      "$ref": "functions.expression.AudioInputSchema"
    },
    {
      "description": "Video content.",
      "$ref": "functions.expression.VideoInputSchema"
    },
    {
      "description": "A file.",
      "$ref": "functions.expression.FileInputSchema"
    }
  ]
}

{
  "title": "functions.expression.VideoInputSchema",
  "description": "Schema for a video input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected video.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "type": {
      "$ref": "functions.expression.VideoInputSchemaType"
    }
  }
}
